// src/components/Dashboard/ReleaseMaster.js
import React, { useEffect, useMemo, useRef, useState } from 'react';

/**
 * [PH1-LOCAL] Try local PPT first from /files, fallback to SharePoint if it fails.
 * Local path expected: /files/PBPT RM - Master.pptx
 * Fallback SP URL (edit/view) is provided via env or the given default link.
 */
export default function ReleaseMaster() {
  const objRef = useRef(null);
  const [useSP, setUseSP] = useState(false);      // [PH1-LOCAL]
  const [localOk, setLocalOk] = useState(false);  // [PH1-LOCAL]

  // Local PPT path (served statically at /files)
  const localUrl = useMemo(() => {
    const fname = 'PBPT RM - Master.pptx';
    return `${window.location.origin}/files/${encodeURIComponent(fname)}`; // [PH1-LOCAL]
  }, []);

  // SharePoint fallback (prefer env)
  const spBase =
    process.env.REACT_APP_SP_RM_MASTER_URL ||
    'https://cibc.sharepoint.com/:p:/r/sites/GRP-PBPTReleaseManagement/Shared%20Documents/General/PBPT%20RM%20-%20Master.pptx?d=w514ce62675c54619824fd1e5e9e26bd2&web=1';

  const spUrl = useMemo(() => {
    const sep = spBase.includes('?') ? '&' : '?';
    // Use embedview to maximize chance of rendering inside an iframe
    return `${spBase}${sep}action=embedview&wdAllowInteractivity=True&embed=1`; // [PH1-LOCAL]
  }, [spBase]);

  useEffect(() => {
    let cancelled = false;

    // 1) HEAD check to ensure the file is reachable from the browser
    (async () => {
      try {
        const res = await fetch(localUrl, { method: 'HEAD', cache: 'no-store' });
        if (!cancelled && res.ok) {
          setLocalOk(true);
          // 2) Give the <object> ~1.2s to render; otherwise assume no native viewer and flip to SP.
          setTimeout(() => {
            if (cancelled) return;
            // If the object didn't load (no contentDocument or empty), fallback
            // Note: Not all browsers expose contentDocument for non-HTML. Timer heuristic is safer.
            if (!objRef.current) return;
            // If we already forced SP, skip
            if (!useSP) {
              // We cannot reliably inspect the PPTX document; retain local unless user sees empty frame.
              // To be safe, keep local; offer manual switch if needed (not adding UI here per scope).
            }
          }, 1200);
        } else if (!cancelled) {
          setUseSP(true);
        }
      } catch {
        if (!cancelled) setUseSP(true);
      }
    })();

    return () => { cancelled = true; };
  }, [localUrl, useSP]);

  return (
    <div style={{ height: '78vh', borderRadius: 12, overflow: 'hidden', background: '#0f162a' }}>
      {!useSP && localOk ? (
        // [PH1-LOCAL] Try native render via <object>. Some browsers download instead of render.
        <object
          ref={objRef}
          data={localUrl}
          type="application/vnd.openxmlformats-officedocument.presentationml.presentation"
          style={{ width: '100%', height: '100%' }}
        >
          {/* Fallback content inside <object> if the browser can't render PPTX */}
          <div style={{ padding: 12 }}>
            <div className="muted" style={{ marginBottom: 8 }}>
              Unable to render PPT locally in this browser. Loading SharePoint viewer…
            </div>
          </div>
        </object>
      ) : (
        // [PH1-LOCAL] SharePoint fallback
        <iframe
          title="PBPT RM - Master (SharePoint)"
          src={spUrl}
          style={{ width: '100%', height: '100%', border: 0 }}
          allow="clipboard-read; clipboard-write; fullscreen"
          allowFullScreen
        />
      )}
    </div>
  );
}
